INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','there-is-there-are','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"there-is-there-are","title":"There is and there are","level":"A1","order":8,"summary":"Describe what exists, ask about it, and give short answers.","learningGoals":["Existence and number","Questions and negatives","Short answers"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Existence and number","explanation":"Use there is before a singular or uncountable noun. Use there are before a plural noun. These exercises use standard written agreement.","examples":["There is a light above the gate.","There are two seats near the exit."]},{"title":"Questions and negatives","explanation":"Put is or are before there to ask a question. Put not after the verb to make a negative.","examples":["Is there a bicycle stand?","There are not any spare chairs."]},{"title":"Short answers","explanation":"Keep there and the matching verb in a short answer. In a positive answer, do not shorten there is to there’s.","examples":["Yes, there is.","No, there are not."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-there-is-there-are"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"quizItems":[{"id":"a364e201-a404-5fdb-acc1-7148074df34c","topicSlug":"there-is-there-are","level":"A1","prompt":"There ____ a clock above the reception desk. Use s